exercises.starterCode:
// Plan de un sitio web con dos servicios detrás de un balanceador. Corrige su defecto principal.
export const plan = {
  carga: "sitio-por-rutas",
  balanceador: { nombre: "lb-web", tipo: "network", capa: 4, reglas: [] },
  gruposDestino: ["api", "imagenes"],
};

solution.code:
export const plan = {
  carga: "sitio-por-rutas",
  balanceador: {
    nombre: "lb-web",
    tipo: "application",
    capa: 7,
    reglas: [
      { condicion: { ruta: "/api/*" }, destino: "api" },
      { condicion: { ruta: "/imagenes/*" }, destino: "imagenes" },
    ],
  },
  gruposDestino: ["api", "imagenes"],
};

spec.code:
for (const grupo of plan.gruposDestino) {
  const regla = plan.balanceador.reglas.find((r) => r.destino === grupo);
  assert.ok(regla, "falta la regla del grupo " + grupo);
  assert.ok(regla.condicion && typeof regla.condicion.ruta === "string", "la regla de " + grupo + " debe tener una condición de ruta");
}

